 "content": "from collections import deque


def transform(grid):
    """Outline enclosed zero regions and place an exterior halo around their walls."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    comp_id = [[-1] * w for _ in range(h)]
    comps = []

    # Label 4-connected components of the 1-colored line drawing.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or comp_id[r][c] >= 0:
                continue
            cid = len(comps)
            q = [(r, c)]
            comp_id[r][c] = cid
            for x, y in q:
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1
                            and comp_id[nx][ny] < 0):
                        comp_id[nx][ny] = cid
                        q.append((nx, ny))
            comps.append(q)

    # Flood all background regions. A region not touching the canvas edge is an interior pocket.
    bg_id = [[-1] * w for _ in range(h)]
    regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or bg_id[r][c] >= 0:
                continue
            rid = len(regions)
            q = [(r, c)]
            bg_id[r][c] = rid
            touches_edge = False
            for x, y in q:
                if x == 0 or x == h - 1 or y == 0 or y == w - 1:
                    touches_edge = True
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0
                            and bg_id[nx][ny] < 0):
                        bg_id[nx][ny] = rid
                        q.append((nx, ny))
            regions.append((q, touches_edge))

    # Activate only line components which actually bound a sealed pocket.
    active = set()
    for cells, touches_edge in regions:
        if touches_edge:
            continue
        for r, c in cells:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and comp_id[nr][nc] >= 0:
                    active.add(comp_id[nr][nc])
                    out[r][c] = 3

    # One-cell inner boundary of every enclosed pocket is 3; an 8-neighbor outer halo is 2.
    for cid in active:
        for r, c in comps[cid]:
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                            and bg_id[nr][nc] >= 0 and regions[bg_id[nr][nc]][1]):
                        out[nr][nc] = 2
    return out


